{
  "bam_nhan_vat_boi_canh": {
    "quote": "Tôi không trả lời.",
    "reason": "Lâm kiệm lời, hay quan sát dòng nước trước khi hành động và bối cảnh xóm sàn, đèn, cọc thề được giữ xuyên suốt. Tuy nhiên Lan và Miếu Bùn xuất hiện đột ngột, việc Lan dập Đèn Chung làm tắt cả xóm là luật mới chưa được gieo, làm lệch bí ẩn ban đầu.",
    "score": 3
  },
  "giong_sang_tao": {
    "quote": "Mép bùn vắng đến nỗi tiếng nước rút dưới chân cọc nghe như ai kéo một tấm vải ướt.",
    "reason": "Giọng u tối, câu ngắn và hình ảnh nước ngược, vết khía dưới bùn, rong căng ngược gió nhất quán, có chi tiết nhớ được. Một số nhịp nước kéo, bùn lún lặp lại nhưng chưa phá giọng riêng.",
    "score": 4
  },
  "lien_mach": {
    "quote": "Ánh đèn trong chiếc lồng đồng đã tắt từ sáng; tim đèn còn ánh màu đỏ âm ỉ, hắt lên nếp nhăn quanh miệng bà.",
    "reason": "Các lựa chọn đã chọn được nhắc lại và có hệ quả, vết khía và khe nước được theo tiếp. Nhưng Đèn Chung đã tắt lại về sau có ngọn lửa nhỏ mà không có cảnh thắp lại, và lời thú nhận của Lan được lặp lại trong cùng chương 6.",
    "score": 3
  },
  "loi": {
    "quote": "Tôi dập Đèn Chung. Tôi muốn mọi người nghe lời khấn ở Miếu Bùn. Không ngờ lửa tắt theo hết cả xóm.",
    "reason": "Không thấy chữ lạ hay đổi ngôi kể, ngôi thứ nhất giữ suốt truyện. Tuy nhiên chương 6 lặp gần nguyên ý lời thú nhận của Lan ở hai đoạn, là lỗi lặp ý rõ làm gián đoạn đọc.",
    "score": 3
  },
  "lua_chon_y_nghia": {
    "quote": "1. [Hành động] Bám lấy đám rễ để ghìm mình lại khỏi bị kéo sâu hơn",
    "reason": "Ba lựa chọn thường tách rõ hành động, lời thoại và nội tâm, mỗi hướng có giá riêng như giữ mạng, cứu người hay mở lối nước. Vài lựa chọn như im lặng về Đèn Chung có hệ quả hơi mỏng, nhưng không trùng ý hay hiển nhiên đúng.",
    "score": 4
  },
  "nhip_day_truyen": {
    "quote": "Căn sàn sát Mép Bùn còn trụ được một nhịp.",
    "reason": "Mỗi chương đều đổi tình thế: tìm khe, mở lối, nhà sụp, ông Bá thú nhận, nước quay về đầm rồi phải phá sàn. Nhịp mở khe và bị nước kéo lặp vài lần, nhưng cuối chương luôn có mất mát hoặc lối đi bị cắt để kéo tiếp.",
    "score": 4
  },
  "tieng_viet_tu_nhien": {
    "quote": "- Đừng gọi cả xóm ra đây.",
    "reason": "Câu văn và đối thoại nhìn chung như tiếng Việt tự nhiên, xưng hô tôi/bà/cô/chị phần lớn hợp quan hệ làng xóm. Vẫn có vài chỗ hơi cứng và cách gọi Lan lúc cô lúc chị chưa thật nhất quán, nên chưa đạt mức không cần sửa.",
    "score": 4
  }
}
